#!/usr/bin/env bash
# One-time (idempotent) set-up of the PneumoVision server. Run as `ubuntu`:
#
#   curl -fsSL https://raw.githubusercontent.com/Ussefemad1/PneumoVision/main/infra/aws/bootstrap.sh -o bootstrap.sh
#   bash bootstrap.sh
#
# What it does, each step skipped when already done:
#   1. clones the repo to ~/PneumoVision -- a *sparse, blob-filtered* clone that
#      never downloads the MIMIC-derived files tracked in git (they never reach
#      this server, not even inside .git);
#   2. writes ~/PneumoVision/.env (mode 600) with every secret generated by
#      openssl: Ed25519 JWT keypair (base64 PEM), field-encryption key, CSRF and
#      HMAC secrets, Redis / Mongo / MinIO passwords, and the seeded admin's
#      password. A rerun keeps every existing value; secrets are never printed,
#      except the admin password, once, when it is first generated;
#   3. writes the Mongo replica-set keyfile (chmod 400, owned by uid 999, the
#      mongodb user of the mongo image);
#   4. creates checkpoints/round3/{mortality,phenotyping}/, the ACME webroot and
#      a self-signed certificate for <ip-with-dashes>.sslip.io (replaced by
#      Let's Encrypt on the first deploy);
#   5. installs a systemd timer that renews the certificate twice a day;
#   6. optionally enables unattended security upgrades (UNATTENDED_UPGRADES=no
#      to skip).
#
# Environment overrides: REPO_URL, BRANCH, PV_DIR, PUBLIC_HOST, ADMIN_EMAIL,
# LETSENCRYPT_EMAIL.
set -euo pipefail

REPO_URL="${REPO_URL:-https://github.com/Ussefemad1/PneumoVision.git}"
BRANCH="${BRANCH:-main}"
PV_DIR="${PV_DIR:-$HOME/PneumoVision}"

say() { printf '\n\033[1m==> %s\033[0m\n' "$*"; }
die() { printf '\nbootstrap: %s\n' "$*" >&2; exit 1; }

[[ "$(id -u)" -ne 0 ]] || die "run as the ubuntu user, not root"
command -v docker >/dev/null || die "docker is not installed"
docker compose version >/dev/null 2>&1 || die "the docker compose plugin is not installed"
docker info >/dev/null 2>&1 || die "cannot talk to docker: is $(id -un) in the docker group? (log out and back in after adding it)"
command -v openssl >/dev/null || die "openssl is not installed"
command -v git >/dev/null || die "git is not installed"

# ── 1. sparse clone ──────────────────────────────────────────────────────────
# Paths left out of the checkout (and, with --filter=blob:none, never
# downloaded): MIMIC-derived resources vendored with medpatch, and the two demo
# PNGs of unknown provenance. Serving needs none of them.
SPARSE_RULES=(
  '/*'
  '!/medpatch/mimic4extract/'
  '!/medpatch/ehr_utils/mimic-cxr-ehr-split.csv'
  '!/medpatch/ehr_utils/resources/valset*.csv'
  '!/docs/demo-examples/*.png'
)
say "Repository ($PV_DIR)"
if [[ ! -d "$PV_DIR/.git" ]]; then
  git clone --filter=blob:none --no-checkout --branch "$BRANCH" "$REPO_URL" "$PV_DIR"
  git -C "$PV_DIR" sparse-checkout set --no-cone "${SPARSE_RULES[@]}"
  git -C "$PV_DIR" checkout "$BRANCH"
else
  git -C "$PV_DIR" sparse-checkout set --no-cone "${SPARSE_RULES[@]}"
  echo "already cloned; sparse rules re-applied"
fi
cd "$PV_DIR"

# ── 2. .env ──────────────────────────────────────────────────────────────────
say "Secrets (.env)"
ENV_FILE="$PV_DIR/.env"
umask 077
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"

has() { grep -q "^$1=" "$ENV_FILE"; }
put() { has "$1" || printf '%s=%s\n' "$1" "$2" >>"$ENV_FILE"; }
hex() { openssl rand -hex "$1"; }

detect_host() {
  local token ip
  token="$(curl -fsS -m 3 -X PUT http://169.254.169.254/latest/api/token \
    -H 'X-aws-ec2-metadata-token-ttl-seconds: 60' 2>/dev/null || true)"
  ip="$(curl -fsS -m 3 -H "X-aws-ec2-metadata-token: $token" \
    http://169.254.169.254/latest/meta-data/public-ipv4 2>/dev/null || true)"
  [[ "$ip" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
  printf '%s.sslip.io' "${ip//./-}"
}
if ! has PUBLIC_HOST; then
  host="${PUBLIC_HOST:-$(detect_host || true)}"
  [[ -n "$host" ]] || die "could not read the public IP from the instance metadata; rerun with PUBLIC_HOST=<ip-with-dashes>.sslip.io"
  put PUBLIC_HOST "$host"
fi

if ! has JWT_PRIVATE_KEY_B64; then
  tmp="$(mktemp -d)"
  openssl genpkey -algorithm ed25519 -out "$tmp/jwt.key" 2>/dev/null
  openssl pkey -in "$tmp/jwt.key" -pubout -out "$tmp/jwt.pub" 2>/dev/null
  put JWT_PRIVATE_KEY_B64 "$(base64 -w0 "$tmp/jwt.key")"
  put JWT_PUBLIC_KEY_B64 "$(base64 -w0 "$tmp/jwt.pub")"
  rm -rf "$tmp"
fi
put FIELD_ENCRYPTION_KEY_HEX "$(hex 32)"
put CSRF_SECRET "$(hex 32)"
put INFERENCE_HMAC_SECRET "$(hex 32)"
put REDIS_PASSWORD "$(hex 24)"
put MONGO_ROOT_USER pvroot
put MONGO_ROOT_PASSWORD "$(hex 24)"
put S3_ACCESS_KEY "pv$(hex 8)"
put S3_SECRET_KEY "$(hex 24)"
put S3_BUCKET pneumovision-cxr
put INFERENCE_MODE fusion
put TORCH_NUM_THREADS 2
put INFERENCE_TIMEOUT_MS 180000
put SEED_DEMO_DATA true
put SEED_ADMIN_EMAIL "${ADMIN_EMAIL:-admin@pneumovision.local}"
[[ -z "${LETSENCRYPT_EMAIL:-}" ]] || put LETSENCRYPT_EMAIL "$LETSENCRYPT_EMAIL"
new_admin_password=""
if ! has SEED_ADMIN_PASSWORD; then
  new_admin_password="$(openssl rand -base64 18 | tr '+/' '-_')"
  put SEED_ADMIN_PASSWORD "$new_admin_password"
fi
echo ".env has $(grep -c '=' "$ENV_FILE") settings (mode $(stat -c %a "$ENV_FILE")); values not shown"
PUBLIC_HOST="$(grep '^PUBLIC_HOST=' "$ENV_FILE" | cut -d= -f2-)"

# ── 3. Mongo keyfile ─────────────────────────────────────────────────────────
say "Mongo keyfile"
KEYFILE="$PV_DIR/infra/mongo/keyfile"
mkdir -p "$(dirname "$KEYFILE")"
if [[ ! -s "$KEYFILE" ]] && ! sudo test -s "$KEYFILE"; then
  openssl rand -base64 756 | sudo tee "$KEYFILE" >/dev/null
fi
sudo chmod 400 "$KEYFILE"
sudo chown 999:999 "$KEYFILE"
echo "$KEYFILE: mode 400, owner 999 (mongodb in the mongo image)"

# ── 4. folders and a stand-in certificate ────────────────────────────────────
say "Folders and certificate"
umask 022
mkdir -p "$PV_DIR/checkpoints/round3/mortality" "$PV_DIR/checkpoints/round3/phenotyping" \
  "$PV_DIR/infra/aws/certbot/www/.well-known/acme-challenge" "$PV_DIR/infra/aws/certbot/conf" \
  "$HOME/backups"
# nginx's healthcheck fetches this file over port 80.
echo ok >"$PV_DIR/infra/aws/certbot/www/.well-known/acme-challenge/pv-health"
if [[ ! -f "$PV_DIR/infra/nginx/certs/server.crt" ]]; then
  CERT_CN="$PUBLIC_HOST" bash "$PV_DIR/infra/scripts/gen-certs.sh" >/dev/null
  echo "self-signed certificate for $PUBLIC_HOST (Let's Encrypt replaces it on the first deploy)"
else
  echo "certificate already present"
fi

# ── 5. certificate renewal timer ─────────────────────────────────────────────
say "Certificate renewal (systemd timer)"
sudo tee /etc/systemd/system/pneumovision-cert-renew.service >/dev/null <<EOF
[Unit]
Description=Renew the PneumoVision Let's Encrypt certificate
After=docker.service network-online.target
Wants=network-online.target

[Service]
Type=oneshot
User=$(id -un)
ExecStart=$PV_DIR/infra/aws/cert.sh renew
EOF
sudo tee /etc/systemd/system/pneumovision-cert-renew.timer >/dev/null <<'EOF'
[Unit]
Description=Twice-daily PneumoVision certificate renewal check

[Timer]
OnCalendar=*-*-* 03,15:00:00
RandomizedDelaySec=1h
# The instance is stopped most of the time: run a missed check at boot.
Persistent=true
OnBootSec=10min

[Install]
WantedBy=timers.target
EOF
sudo systemctl daemon-reload
sudo systemctl enable --now pneumovision-cert-renew.timer >/dev/null
echo "pneumovision-cert-renew.timer enabled"

# ── 6. unattended security upgrades ──────────────────────────────────────────
if [[ "${UNATTENDED_UPGRADES:-yes}" == "yes" ]]; then
  say "Unattended security upgrades"
  if ! dpkg -s unattended-upgrades >/dev/null 2>&1; then
    sudo apt-get update -qq && sudo DEBIAN_FRONTEND=noninteractive apt-get install -y -qq unattended-upgrades
  fi
  echo 'unattended-upgrades unattended-upgrades/enable_auto_updates boolean true' | sudo debconf-set-selections
  sudo DEBIAN_FRONTEND=noninteractive dpkg-reconfigure -f noninteractive unattended-upgrades
  echo "enabled (security updates only; no automatic reboot)"
fi

# Docker must come back by itself when the instance starts.
sudo systemctl enable docker >/dev/null 2>&1 || true

say "Done"
cat <<EOF
Site:   https://$PUBLIC_HOST   (after deploy)
Admin:  $(grep '^SEED_ADMIN_EMAIL=' "$ENV_FILE" | cut -d= -f2-)
EOF
if [[ -n "$new_admin_password" ]]; then
  cat <<EOF
Admin password (shown ONCE -- store it in your password manager now):

    $new_admin_password

EOF
else
  echo "Admin password: unchanged (kept in $ENV_FILE as SEED_ADMIN_PASSWORD)"
fi
cat <<EOF
Next: copy the checkpoints (infra/aws/copy-checkpoints.md), then run
    $PV_DIR/infra/aws/deploy.sh
EOF
